@import url('https://fonts.googleapis.com/css2?family=inter:wght@400;600;700&display=swap');

/* ===== Reset ===== */
*, *::before, *::after {
  box-sizing: border-box;
  margin: 0;
  padding: 0;
}

/* ===== Page ===== */
body {
  min-height: 100vh;
  display: flex;
  align-items: center;
  justify-content: center;
  background: #1A1A1A;
  font-family: "Inter", sans-serif;
}

/* ===== Ad Wrapper ===== */
#ad-300x600 {
  width: 300px;
  height: 600px;
  background: #FFED00;
  overflow: hidden;
  position: relative;
  display: flex;
  flex-direction: column;
  border: 2px solid #000000;
}

/* ===== Header ===== */
.ad-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  background: #E3000B;
  padding: 8px 12px;
  flex-shrink: 0;
}

.ad-logo {
  height: 36px;
  width: auto;
  display: block;
}

.eyebrow {
  font-family: "Inter", sans-serif;
  font-size: 10px;
  font-weight: 700;
  color: #FFFFFF;
  letter-spacing: 0.08em;
  text-transform: uppercase;
  background: rgba(0,0,0,0.25);
  padding: 3px 7px;
  border-radius: 3px;
}

/* ===== Headline Block ===== */
.ad-headline-block {
  background: #FFED00;
  padding: 10px 14px 6px 14px;
  flex-shrink: 0;
  position: relative;
  z-index: 1;
}

.headline {
  font-family: "Inter", sans-serif;
  font-size: 26px;
  font-weight: 700;
  line-height: 1.05;
  color: #000000;
  letter-spacing: -0.01em;
  text-transform: uppercase;
}

.headline em {
  font-style: normal;
  color: #006DB7;
  display: block;
  font-size: 30px;
  font-weight: 700;
  -webkit-text-stroke: 1.5px #000000;
  text-shadow: 2px 2px 0 rgba(0,0,0,0.18);
}

.subhead {
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 500;
  color: #1A1A1A;
  margin-top: 4px;
  line-height: 1.4;
}

/* ===== Slideshow ===== */
.slideshow {
  position: relative;
  flex: 1 1 auto;
  overflow: hidden;
  background: #F2F2F2;
  min-height: 0;
}

.slide {
  position: absolute;
  inset: 0;
  display: flex;
  flex-direction: column;
  align-items: center;
  justify-content: center;
  opacity: 0;
  transform: translateX(40px);
  transition: opacity 0.45s ease, transform 0.45s ease;
  pointer-events: none;
}

.slide.active {
  opacity: 1;
  transform: translateX(0);
  pointer-events: auto;
}

.slide.exit {
  opacity: 0;
  transform: translateX(-40px);
  transition: opacity 0.35s ease, transform 0.35s ease;
}

.slide-img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  object-position: center;
  display: block;
}

/* Caption */
.slide-caption {
  position: absolute;
  bottom: 0;
  left: 0;
  right: 0;
  background: rgba(0,0,0,0.52);
  padding: 5px 10px;
  text-align: center;
}

.slide-label {
  font-family: "Inter", sans-serif;
  font-size: 11px;
  font-weight: 600;
  color: #FFED00;
  letter-spacing: 0.04em;
  text-transform: uppercase;
}

/* Dots */
.slide-dots {
  position: absolute;
  top: 8px;
  left: 50%;
  transform: translateX(-50%);
  display: flex;
  gap: 5px;
  z-index: 10;
}

.dot {
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background: rgba(255,255,255,0.5);
  border: 1.5px solid #000000;
  cursor: pointer;
  transition: background 0.25s, transform 0.2s;
  padding: 0;
}

.dot.active {
  background: #FFED00;
  transform: scale(1.25);
}

.dot:hover {
  background: rgba(255,237,0,0.8);
}

/* Arrows */
.arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  background: rgba(0,0,0,0.45);
  color: #FFFFFF;
  border: none;
  font-size: 22px;
  line-height: 1;
  width: 26px;
  height: 34px;
  cursor: pointer;
  z-index: 10;
  display: flex;
  align-items: center;
  justify-content: center;
  transition: background 0.2s;
  border-radius: 2px;
}

.arrow:hover {
  background: rgba(227,0,11,0.8);
}

.arrow-prev { left: 4px; }
.arrow-next { right: 4px; }

/* ===== Body copy ===== */
.ad-body {
  background: #FFED00;
  padding: 7px 14px 4px 14px;
  flex-shrink: 0;
}

.body-copy {
  font-family: "Inter", sans-serif;
  font-size: 11.5px;
  font-weight: 400;
  color: #1A1A1A;
  line-height: 1.45;
  text-align: center;
}

.body-copy strong {
  font-weight: 700;
  color: #006DB7;
}

/* ===== CTA ===== */
.ad-cta-block {
  background: #FFED00;
  padding: 0 14px 8px 14px;
  flex-shrink: 0;
  display: flex;
  justify-content: center;
}

.cta-btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  background: #E3000B;
  color: #FFFFFF;
  text-decoration: none;
  border-radius: 4px;
  padding: 10px 20px;
  border: 2.5px solid #000000;
  box-shadow: 3px 3px 0 #000000;
  transition: transform 0.15s, box-shadow 0.15s, background 0.15s;
  width: 100%;
  max-width: 240px;
}

.cta-btn:hover {
  background: #000000;
  transform: translateY(-2px);
  box-shadow: 3px 5px 0 rgba(0,0,0,0.5);
}

.cta-btn:active {
  transform: translateY(1px);
  box-shadow: 1px 1px 0 #000000;
}

.cta-label {
  font-family: "Inter", sans-serif;
  font-size: 13px;
  font-weight: 700;
  letter-spacing: 0.04em;
  text-transform: uppercase;
  color: #FFFFFF;
}

/* ===== Footer ===== */
.ad-footer {
  background: #000000;
  padding: 5px 10px 7px 10px;
  flex-shrink: 0;
}

.ad-footer span {
  font-family: "Inter", sans-serif;
  font-size: 7.5px;
  font-weight: 400;
  color: rgba(255,255,255,0.7);
  line-height: 1.3;
  display: block;
  text-align: center;
}

/* ===== Reduced motion ===== */
@media (prefers-reduced-motion: reduce) {
  .slide {
    transition: opacity 0.15s ease;
    transform: none !important;
  }
  .slide.exit {
    transition: opacity 0.1s ease;
    transform: none !important;
  }
}

